&lt;h3 id=&#34;商品与基础数据&#34;&gt;&lt;a href=&#34;#商品与基础数据&#34; class=&#34;headerlink&#34; title=&#34;商品与基础数据&#34;&gt;&lt;/a&gt;商品与基础数据&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;功能&lt;/th&gt;
&lt;th style=&#34;text-align:center&#34;&gt;Lite（开源）&lt;/th&gt;
